import { z } from 'zod';

// Admin export — a snapshot of data freshness + completeness across all
// sources. Generated by the admin dashboard (prompt 13). Intended for
// the data engineering team, not Council, so ornament is minimal.
export const DataQualityReportDataSchema = z.object({
  dateLabel: z.string(),
  author: z.string().optional(),
  summary: z.string(),
  sources: z.array(
    z.object({
      id: z.string(),
      name: z.string(),
      kind: z.enum(['API', 'PDF', 'CSV', 'SCRAPE']),
      lastSyncedAt: z.string().nullable(),
      status: z.string(),
      coveragePercent: z.number().min(0).max(100).optional(),
      issues: z.array(z.string()).default([]),
    }),
  ),
});
export type DataQualityReportData = z.infer<typeof DataQualityReportDataSchema>;
